package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.*;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.ObjectIdReader;
import com.fasterxml.jackson.databind.deser.impl.ObjectIdResolver;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.PropertyMetadata;
import java.io.*;
import java.io.IOException;
import java.lang.annotation.Annotation;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class ObjectIdValueProperty_deserializeSetAndReturn_TriageGen0Test {

    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private JsonDeserializer<Object> mockValueDeserializer;
    private ObjectIdReader mockObjectIdReader;
    private SettableBeanProperty mockIdProp;
    private ReadableObjectId mockReadableObjectId;
    private PropertyMetadata mockMetadata;
    private Object mockInstance;
    private Object testId = "test-id-123";

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockValueDeserializer = mock(JsonDeserializer.class);
        mockObjectIdReader = mock(ObjectIdReader.class);
        mockIdProp = mock(SettableBeanProperty.class);
        mockReadableObjectId = mock(ReadableObjectId.class);
        mockMetadata = mock(PropertyMetadata.class);
        mockInstance = new Object();

        // Setup ObjectIdReader internal fields via reflection or mock behavior
        // Since ObjectIdReader fields are package-private/public in Jackson, we mock the structure
        mockObjectIdReader.generator = mock(ObjectIdResolver.class);
        mockObjectIdReader.resolver = mock(ObjectIdResolver.class);
        mockObjectIdReader.idProperty = mockIdProp;

        // Default behavior for finding ObjectId
        when(mockContext.findObjectId(eq(testId), any(), any())).thenReturn(mockReadableObjectId);
    }

    private ObjectIdValueProperty createSut() {
        ObjectIdValueProperty property = new ObjectIdValueProperty(mockObjectIdReader, mockMetadata);
        // We need to inject the value deserializer because it's used in the method
        // In actual Jackson, this is set via internal setter or constructor
        // Since the provided code uses _valueDeserializer, we assume it's accessible or set via a method
        // For the purpose of this test, we use reflection to set the private field if necessary, 
        // but usually, we can use the provided 'withValueDeserializer' if available.
        return property.withValueDeserializer(mockValueDeserializer);
    }

    @Test
    public void testDeserializeSetAndReturn_ReturnsNullWhenIdIsNull() throws IOException {
        ObjectIdValueProperty sut = createSut();
        when(mockValueDeserializer.deserialize(mockParser, mockContext)).thenReturn(null);

        Object result = sut.deserializeSetAndReturn(mockParser, mockContext, mockInstance);

        assertNull(result);
        verify(mockValueDeserializer).deserialize(mockParser, mockContext);
        verifyNoInteractions(mockContext);
        verifyNoInteractions(mockReadableObjectId);
    }

    @Test
    public void testDeserializeSetAndReturn_WithIdProp_ReturnsIdPropValue() throws IOException {
        ObjectIdValueProperty sut = createSut();
        when(mockValueDeserializer.deserialize(mockParser, mockContext)).thenReturn(testId);
        when(mockIdProp.setAndReturn(eq(mockInstance), eq(testId))).thenReturn(testId);

        Object result = sut.deserializeSetAndReturn(mockParser, mockContext, mockInstance);

        assertEquals(testId, result);
        verify(mockReadableObjectId).bindItem(mockInstance);
        verify(mockIdProp).setAndReturn(mockInstance, testId);
    }

    @Test
    public void testDeserializeSetAndReturn_WithoutIdProp_ReturnsInstance() throws IOException {
        // Setup reader without idProperty
        mockObjectIdReader.idProperty = null;
        ObjectIdValueProperty sut = createSut();

        when(mockValueDeserializer.deserialize(mockParser, mockContext)).thenReturn(testId);

        Object result = sut.deserializeSetAndReturn(mockParser, mockContext, mockInstance);

        assertEquals(mockInstance, result);
        verify(mockReadableObjectId).bindItem(mockInstance);
        verifyNoInteractions(mockIdProp);
    }

    @Test(expected = IOException.class)
    public void testDeserializeSetAndReturn_ThrowsExceptionOnDeserializerError() throws IOException {
        ObjectIdValueProperty sut = createSut();
        when(mockValueDeserializer.deserialize(mockParser, mockContext)).thenThrow(new IOException("Deserialization failed"));

        sut.deserializeSetAndReturn(mockParser, mockContext, mockInstance);
    }

    @Test(expected = IOException.class)
    public void testDeserializeSetAndReturn_ThrowsExceptionOnBindItemError() throws IOException {
        ObjectIdValueProperty sut = createSut();
        when(mockValueDeserializer.deserialize(mockParser, mockContext)).thenReturn(testId);
        doThrow(new IOException("Bind failed")).when(mockReadableObjectId).bindItem(mockInstance);

        sut.deserializeSetAndReturn(mockParser, mockContext, mockInstance);
    }
}
